import java.util.*;

public class Main {
    ListNode removeElements(ListNode head, int val) {
        List<Integer> values = new ArrayList<>();
        for (ListNode node = head; node != null; node = node.next) {
            if (node.val != val) values.add(node.val);                            // keep only values that don't match
        }
        ListNode dummy = new ListNode(0);
        ListNode cur = dummy;
        for (int v : values) {
            cur.next = new ListNode(v);                                             // rebuild a brand new list from the filtered values
            cur = cur.next;
        }
        return dummy.next;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(1, new ListNode(2, new ListNode(6, new ListNode(3, new ListNode(4, new ListNode(5, new ListNode(6)))))));
        ListNode result = solution.removeElements(head, 6);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

